node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8000',{waitUntil:'networkidle'});await page.getByRole('button',{name:/Pass & Play/}).click();
 let plays=0;
 for(;plays<150;plays++){
   if(await page.getByRole('button',{name:'NEW GAME'}).count())break;
   if(await page.getByRole('button',{name:/Extra point/}).count()){await page.getByRole('button',{name:/Extra point/}).click();continue}
   const offense=page.locator('.match-card[data-type="offense"]');
   if(await offense.count()){await offense.first().click();await page.getByRole('button',{name:/SNAP THE BALL/}).click();continue}
   const ready=page.getByRole('button',{name:/DEFENSE IS READY/});
   if(await ready.count()){await ready.click();continue}
   const defense=page.locator('.match-card[data-type="defense"]');
   if(await defense.count()){await defense.first().click();await page.getByRole('button',{name:/REVEAL THE PLAY/}).click();continue}
   throw new Error('Unrecognized state: '+await page.locator('#cardMatch').innerText());
 }
 const final=await page.locator('#cardMatch').innerText();
 if(!final.includes('FINAL WHISTLE'))throw new Error(`game did not finish in ${plays} plays: ${final.slice(0,200)}`);
 if(errors.length)throw new Error(errors.join('\n'));
 console.log(JSON.stringify({finalTest:'passed',resolvedPlays:plays,score:await page.locator('#recordLabel').textContent(),clock:await page.locator('#clockLabel').textContent(),errors}));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
