 await page.goto('http://127.0.0.1:8000',{waitUntil:'networkidle'});await page.evaluate(()=>{Math.random=()=>0.5});await page.locator('.mode-choice[data-mode="pass"]').click();
 let turns=0, conversions=0;
 for(;turns<1100;turns++){
   if(await page.locator('#cardMatch [data-action="menu"]').count())break;
   if(await page.locator('#cardMatch [data-action="kick-xp"]').count()){conversions++;await page.locator('#cardMatch [data-action="kick-xp"]').click();continue}
   const offense=page.locator('.match-card[data-type="offense"]');
