   const ready=page.locator('#cardMatch [data-action="ready"]');
   if(await ready.count()){await ready.click();continue}
   const defense=page.locator('.match-card[data-type="defense"]');
   if(await defense.count()){await defense.nth(1).click();await page.locator('#cardMatch [data-action="reveal"]').click();continue}
   throw new Error('Unrecognized state: '+await page.locator('#cardMatch').innerText());
 }
 const score=await page.locator('#recordLabel').textContent();const final=await page.locator('#cardMatch').innerText();
 if(!final.includes('FINAL WHISTLE')||conversions<1||score==='0–0')throw new Error(`score/conversion endgame failed (${turns} turns, conversions=${conversions}, score=${score}): ${final.slice(0,240)}`);
 if(errors.length)throw new Error(errors.join('\n'));
 console.log(JSON.stringify({scoringEndToEnd:'passed',turns,score,conversions,clock:await page.locator('#clockLabel').textContent(),errors}));
